\set ON_ERROR_STOP on
-- Run from project root: psql -d cafestock -f sql/schema.sql -f sql/import.sql
BEGIN;
\copy regions (region_id, region_name, city, region_level) FROM 'output/regions.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy branches (branch_id, business_name, branch_name, region_id, timezone, source_location_proxy) FROM 'output/branches.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy categories (category_id, category_name) FROM 'output/categories.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy suppliers (supplier_id, supplier_name, lead_time_days) FROM 'output/suppliers.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy ingredients (ingredient_id, ingredient_name, unit, shelf_life_days, unit_cost_idr, package_size, minimum_order_qty, supplier_id) FROM 'output/ingredients.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy products (product_id, product_name, category_id, source_product_type_proxy, base_price_idr) FROM 'output/products.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy recipes (recipe_id, product_id, version) FROM 'output/recipes.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy recipe_ingredients (recipe_ingredient_id, recipe_id, ingredient_id, quantity) FROM 'output/recipe_ingredients.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy market_trends (trend_id, region_id, category_id, week_start, available_at, interest_index, provenance) FROM 'output/market_trends.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy social_posts (post_id, platform, source_post_key, source_url, content_text, published_at, collected_at, batch_key, region_id, location_evidence, language, provenance) FROM 'output/social_posts.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy menu_mentions (mention_id, post_id, product_id, sentiment_label, label_provenance) FROM 'output/menu_mentions.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy menu_aspects (menu_aspect_id, mention_id, aspect, sentiment_label) FROM 'output/menu_aspects.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy menu_market_signals (signal_id, region_id, product_id, period_start, available_at, source_max_published_at, post_count, positive_count, neutral_count, negative_count, mixed_count, sentiment_mean, provenance) FROM 'output/menu_market_signals.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy latent_demand (demand_id, branch_id, product_id, transaction_at, requested_qty, unit_price_idr) FROM 'output/latent_demand.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy transactions (transaction_id, branch_id, transaction_at) FROM 'output/transactions.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy transaction_items (transaction_item_id, transaction_id, demand_id, product_id, requested_qty, fulfilled_qty, unit_price_idr) FROM 'output/transaction_items.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy purchase_orders (purchase_order_id, branch_id, supplier_id, ordered_at, expected_delivery_at, delivered_at, status) FROM 'output/purchase_orders.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy purchase_order_items (purchase_order_item_id, purchase_order_id, ingredient_id, quantity, unit_cost_idr) FROM 'output/purchase_order_items.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy inventory_movements (movement_id, branch_id, ingredient_id, movement_at, movement_type, quantity, transaction_item_id, purchase_order_item_id) FROM 'output/inventory_movements.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy inventory_snapshots (snapshot_id, branch_id, ingredient_id, date, opening_stock, receipts, consumption, waste, adjustments, closing_stock) FROM 'output/inventory_snapshots.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy stockout_events (stockout_event_id, transaction_item_id, ingredient_id, event_at, shortage_qty, unfulfilled_product_qty) FROM 'output/stockout_events.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy waste_records (waste_id, movement_id, reason, quantity) FROM 'output/waste_records.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy restock_decision_dataset (decision_id, branch_id, ingredient_id, decision_at, history_days, mean_daily_consumption_14d, on_hand, on_order, lead_time_days, shelf_life_days, package_size, minimum_order_qty, baseline_purchase_qty, market_interest_latest, market_interest_lag_1w, market_feature_max_at, social_post_count_latest_month, menu_sentiment_latest_month, social_feature_max_at, social_available_at, social_period_start, social_data_available, social_age_days, label_window_end, future_stockout_7d, label_observed, split) FROM 'output/restock_decision_dataset.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy inventory_risk_ml_dataset (risk_row_id, branch_id, ingredient_id, decision_at, history_days, mean_daily_consumption_14d, on_hand, on_order, lead_time_days, shelf_life_days, package_size, minimum_order_qty, baseline_purchase_qty, market_interest_latest, market_interest_lag_1w, market_feature_max_at, social_post_count_latest_month, menu_sentiment_latest_month, social_feature_max_at, social_available_at, social_period_start, social_data_available, social_age_days, label_window_end, target_stockout, label_observed, split, risk_label) FROM 'output/inventory_risk_ml_dataset.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy sentiment_ml_dataset (sentiment_row_id, mention_id, post_id, product_id, region_id, published_at, collected_at, content_text, sentiment_label, label_provenance, split, text_fingerprint, training_status) FROM 'output/sentiment_ml_dataset.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
\copy trend_ml_dataset (trend_row_id, category_id, decision_at, interest_lag_1w, feature_max_at, target_fulfilled_units_next_7d, label_observed, split) FROM 'output/trend_ml_dataset.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '')
COMMIT;
